(gen_random_uuid(), '616ba45c-1d0a-4266-b715-536ea8265c95', 'a', 'Aterosclerose subclínica detectada por métodos de imagem, especialmente escore de cálcio coronário, prediz desfechos cardiovasculares e auxilia na decisão terapêutica.', false),
(gen_random_uuid(), '616ba45c-1d0a-4266-b715-536ea8265c95', 'b', 'Em adultos, a tomografia com escore de cálcio coronário pode adicionar importante valor prognóstico, particularmente para indivíduos considerados em risco intermediário.', false),
(gen_random_uuid(), '616ba45c-1d0a-4266-b715-536ea8265c95', 'c', 'Escore de cálcio zero e ausência de tabagismo, diabetes ou antecedentes familiares de doença coronariana prematura sugerem boa evolução livre de desfechos ateroscleróticos, permitindo postergar a prescrição de hipolipemiantes.', false),
(gen_random_uuid(), '616ba45c-1d0a-4266-b715-536ea8265c95', 'd', 'Em indivíduos sem sintomas, o escore de cálcio não é útil para reclassificar, para cima ou para baixo, a chance de eventos coronarianos.', true),
(gen_random_uuid(), '616ba45c-1d0a-4266-b715-536ea8265c95', 'e', 'Em caso de escore de cálcio 1-99 U Agatston e/ou percentil 75 ou superior, deve-se considerar uso de estatina, especialmente se idade maior que 55 anos.', false),

(gen_random_uuid(), '310a148c-556b-4a4b-a3eb-a4340301863c', 'a', 'Trata-se de paciente com angina rapidamente progressiva, devendo ser indicada a coronariografia como estratégia inicial.', false),
(gen_random_uuid(), '310a148c-556b-4a4b-a3eb-a4340301863c', 'b', 'Trata-se de síndrome coronariana aguda em paciente com dor torácica atípica, devendo ser considerada a revascularização imediata.', false),
(gen_random_uuid(), '310a148c-556b-4a4b-a3eb-a4340301863c', 'c', 'Paciente com baixa probabilidade pré-teste de ter obstrução coronária, com base em idade, sexo e sintomas.', false),
(gen_random_uuid(), '310a148c-556b-4a4b-a3eb-a4340301863c', 'd', 'Paciente com dor torácica não anginosa. Orientações para evitar esforços físicos e encaminhamento para investigação de patologia gastroesofágica.', false),
(gen_random_uuid(), '310a148c-556b-4a4b-a3eb-a4340301863c', 'e', 'Paciente com dor torácica típica e com alta probabilidade pré-teste, devendo ser considerada a avaliação funcional da perfusão miocárdica e o tratamento clínico otimizado para controle dos sintomas como estratégia inicial.', true),

(gen_random_uuid(), '95916c45-cea3-4746-9dde-ba56a8cac0b4', 'a', 'Fração de ejeção do ventrículo esquerdo em repouso entre 35% e 49%.', false),
(gen_random_uuid(), '95916c45-cea3-4746-9dde-ba56a8cac0b4', 'b', 'Escore de cálcio coronariano entre 100 e 399 unidades Agatston.', false),
(gen_random_uuid(), '95916c45-cea3-4746-9dde-ba56a8cac0b4', 'c', 'Escore de Duke > 5.', true),
(gen_random_uuid(), '95916c45-cea3-4746-9dde-ba56a8cac0b4', 'd', 'Dilatação do ventrículo esquerdo estresse-induzida.', false),
(gen_random_uuid(), '95916c45-cea3-4746-9dde-ba56a8cac0b4', 'e', 'Padrão obstrutivo uniarterial com lesão ≥ 70%.', false),

(gen_random_uuid(), 'f9b3e5ee-ac3b-4902-aede-cf245589e0b4', 'a', 'apesar de maior dose, melhor qualidade das imagens e maior facilidade de manuseio, a cintilografia permite que os estudos com agentes marcados por 99mTc estejam indicados como primeira escolha para pesquisa de isquemia concomitante a miocárdio viável', true),
(gen_random_uuid(), 'f9b3e5ee-ac3b-4902-aede-cf245589e0b4', 'b', 'dilatação transitória do ventrículo esquerdo durante a fase de estresse na cintilografia de perfusão do miocárdio representa isquemia extensa', false),
(gen_random_uuid(), 'f9b3e5ee-ac3b-4902-aede-cf245589e0b4', 'c', 'o estresse com exercício é a modalidade preferida para induzir hiperemia coronariana, pois permite a correlação entre os sintomas em esforço e o padrão de perfusão, fornecendo informações prognósticas relativas ao próprio exercício', false),
(gen_random_uuid(), 'f9b3e5ee-ac3b-4902-aede-cf245589e0b4', 'd', 'a heterogeneidade no fluxo sanguíneo miocárdico, induzido pelo estresse farmacológico com dipiridamol, é o que explica a hipocaptação na área irrigada pelo vaso estenótico', false),
(gen_random_uuid(), 'f9b3e5ee-ac3b-4902-aede-cf245589e0b4', 'e', 'são obtidos níveis maiores de fluxo coronariano durante o estresse farmacológico vasodilatador coronariano comparado com o exercício, possivelmente devido a um aumento da resistência ao fluxo com o exercício, causado pelas maiores pressões subendocárdicas', false),

(gen_random_uuid(), '6da63036-0bc2-4ac6-a795-3ac81a51a73c', 'a', 'A angiotomografia de coronárias é o exame de escolha nesse paciente, uma vez que apresenta probabilidade intermediária-alta de doença arterial coronariana.', false),
(gen_random_uuid(), '6da63036-0bc2-4ac6-a795-3ac81a51a73c', 'b', 'Dada a ausência de alterações eletrocardiográfica e/ou disfunção ventricular, não é necessário prosseguir com estratificação de risco adicional.', false),
(gen_random_uuid(), '6da63036-0bc2-4ac6-a795-3ac81a51a73c', 'c', 'Outras etiologias para a dor torácica apresentada devem ser investigadas, uma vez que a ausência de alterações eletrocardiográficas e no ecocardiograma reduz a probabilidade de doença arterial coronariana obstrutiva.', false),
(gen_random_uuid(), '6da63036-0bc2-4ac6-a795-3ac81a51a73c', 'd', 'Dada a alta probabilidade pré-teste para doença coronária, é recomendado prosseguir com o diagnóstico e a estratificação da doença, preferencialmente com cintilografia de perfusão miocárdica ou ecocardiograma com estresse.', true),
(gen_random_uuid(), '6da63036-0bc2-4ac6-a795-3ac81a51a73c', 'e', 'A cineangiocoronariografia é mandatória nesse paciente, uma vez que apresenta alta probabilidade pré-teste de doença arterial coronariana.', false),

(gen_random_uuid(), '4fe2c10c-0e18-4149-b36a-6fc9ae07d8fc', 'a', 'Há um defeito irreversível na parede anterior e na parede lateral consistente com infarto prévio nos territórios do ramo interventricular anterior e do ramo circunflexo da artéria coronária esquerda, respectivamente.', false),
(gen_random_uuid(), '4fe2c10c-0e18-4149-b36a-6fc9ae07d8fc', 'b', 'Há um defeito reversível na parede anterior e na parede inferior consistente com isquemia estresse-induzida nos territórios do ramo interventricular anterior da artéria coronária esquerda e da artéria coronária direita, respectivamente.', false),
(gen_random_uuid(), '4fe2c10c-0e18-4149-b36a-6fc9ae07d8fc', 'c', 'Há um defeito reversível na parede anterior secundário ao BRE e um defeito irreversível na parede lateral consistente com infarto prévio do ramo circunflexo da artéria coronária esquerda.', false),
(gen_random_uuid(), '4fe2c10c-0e18-4149-b36a-6fc9ae07d8fc', 'd', 'Há um defeito reversível na parede anterior e na parede lateral consistente com isquemia estresse-induzida nos territórios do ramo interventricular anterior e do ramo circunflexo da artéria coronária esquerda, respectivamente.', true),
(gen_random_uuid(), '4fe2c10c-0e18-4149-b36a-6fc9ae07d8fc', 'e', 'Os defeitos de perfusão são artefatos associados ao BRE e à atenuação mamária e não são consistentes, portanto, com isquemia miocárdica.', false),

(gen_random_uuid(), 'edad2859-2cc4-4df0-b3c2-a2ef6767c213', 'a', 'O paciente deve ser orientado quanto a modificações de estilo de vida imediatamente e precisa ser submetido a um teste ergométrico tão logo seja possível para diagnóstico de angina estável; além disso, ajustar níveis pressóricos e ser orientado quanto a uso de estatina e acompanhamento regular de colesterol e níveis pressóricos.', false),
(gen_random_uuid(), 'edad2859-2cc4-4df0-b3c2-a2ef6767c213', 'b', 'O paciente tem o diagnóstico de angina estável e, portanto, deve ser orientado quanto a modificações de estilo de vida. Deve ajustar níveis pressóricos e iniciar uso de aspirina na dose de 200 mg/dia; deve ser iniciada estatina prontamente e encaminhado à coronariografia nas próximas 48 horas para avaliação da anatomia coronariana.', false),
(gen_random_uuid(), 'edad2859-2cc4-4df0-b3c2-a2ef6767c213', 'c', 'O paciente só terá o diagnóstico de angina estável após exame complementar confirmatório, como teste ergométrico ou cintilografia miocárdica; deve ser orientado quanto a controle de níveis pressóricos e mudança do estilo de vida, além de controle de níveis de colesterol com estatina. Se confirmado, deve-se iniciar AAS e estatina e avaliar coronariografia.', false),
(gen_random_uuid(), 'edad2859-2cc4-4df0-b3c2-a2ef6767c213', 'd', 'O paciente tem o diagnóstico de angina estável e deve ter seus níveis pressóricos controlados de forma otimizada, além de iniciar estatina; deve ser orientado quanto a modificações de estilo de vida e uso diário de aspirina na dose de 100 mg/dia e encaminhado à coronariografia eletivamente para estratificação anatômica de doença coronariana estável.', false),
(gen_random_uuid(), 'edad2859-2cc4-4df0-b3c2-a2ef6767c213', 'e', 'O paciente tem o diagnóstico clínico de angina estável, e deve ser orientado quanto a modificações de estilo de vida; deve-se otimizar o tratamento da hipertensão arterial e iniciar uma estatina. AAS deve ser iniciado na dose de 100 mg/dia; após otimização terapêutica e controle de duplo produto, deve ser avaliado quanto à melhora dos sintomas; caso permaneçam, pode-se avaliar a coronariografia.', true),

(gen_random_uuid(), '279ac2e8-e29e-4675-9f98-22fc06f58f01', 'a', 'Angina associada à dispneia.', false),
(gen_random_uuid(), '279ac2e8-e29e-4675-9f98-22fc06f58f01', 'b', 'Queda da pressão arterial sistólica com o incremento da carga de esforço no teste ergométrico.', false),
(gen_random_uuid(), '279ac2e8-e29e-4675-9f98-22fc06f58f01', 'c', 'Pressão diastólica final do ventrículo esquerdo menor que 12 mmHg durante o cateterismo.', true),
(gen_random_uuid(), '279ac2e8-e29e-4675-9f98-22fc06f58f01', 'd', 'Estenose crítica proximal em artéria descendente anterior.', false),
(gen_random_uuid(), '279ac2e8-e29e-4675-9f98-22fc06f58f01', 'e', 'Escore de Duke menor que -12 durante a realização de teste ergométrico.', false),

(gen_random_uuid(), '4d590a43-91fc-4f7c-a23f-b5be9733019b', 'a', 'A artéria coronária direita dominante e seus ramos fornecem vascularização para o átrio direito, o ventrículo direito, o septo interventricular posterior e parte do ventrículo esquerdo, incluindo o músculo papilar posteromedial.', false),
(gen_random_uuid(), '4d590a43-91fc-4f7c-a23f-b5be9733019b', 'b', 'O termo "dominância" é usado para se referir à origem do ramo interventricular posterior, sendo direita na maioria dos casos.', false),
(gen_random_uuid(), '4d590a43-91fc-4f7c-a23f-b5be9733019b', 'c', 'O seio coronário é a principal veia cardíaca e recebe a veia cardíaca magna na sua extremidade esquerda e as veias cardíacas parva e média na sua extremidade direita.', false),
(gen_random_uuid(), '4d590a43-91fc-4f7c-a23f-b5be9733019b', 'd', 'Os ramos diagonais irrigam a porção anterior do septo interventricular.', true),
(gen_random_uuid(), '4d590a43-91fc-4f7c-a23f-b5be9733019b', 'e', 'As veias cardíacas mínimas (veias de Tebésio) e veias cardíacas anteriores drenam diretamente as câmaras cardíacas, principalmente no ventrículo direito, sendo responsáveis por pequena parte da drenagem venosa do coração.', false),

(gen_random_uuid(), 'c8dfb000-cb92-44f6-973d-6f234acfce37', 'a', 'A utilização do EC é recomendada em indivíduos sintomáticos ou para avaliação da progressão de aterosclerose.', true),
(gen_random_uuid(), 'c8dfb000-cb92-44f6-973d-6f234acfce37', 'b', 'Valor de EC alto (> 100 ou > percentil 75 para a idade e sexo) significa fator agravante para DAC e risco alto de eventos clínicos em dois a cinco anos.', false),
(gen_random_uuid(), 'c8dfb000-cb92-44f6-973d-6f234acfce37', 'c', 'EC negativo - Calcificação de Artérias Coronárias (CAC) = 0 - indica baixa probabilidade de Doença Arterial Coronária (DAC) e de eventos cardiovasculares futuros.', false),
(gen_random_uuid(), 'c8dfb000-cb92-44f6-973d-6f234acfce37', 'd', 'A quantificação da CAC pode alterar a conduta clínica, principalmente em pacientes assintomáticos de risco intermediário e naqueles de baixo risco com antecedente familiar de DAC precoce.', false),
(gen_random_uuid(), 'c8dfb000-cb92-44f6-973d-6f234acfce37', 'e', 'Medida da CAC é preditora independente de eventos e acrescenta valor prognóstico em relação aos fatores de risco tradicionais de Framingham e à Proteína C Reativa (PCR) e a espessura médio intimal.', false),

(gen_random_uuid(), '0d201f5c-241a-46fa-aa1f-abb929e14340', 'a', 'Na imagem A, observamos uma imagem característica de placa complexa, provavelmente rota, na artéria descendente anterior, envolvendo um ramo diagonal.', false),
(gen_random_uuid(), '0d201f5c-241a-46fa-aa1f-abb929e14340', 'b', 'Na imagem B, observamos uma súbita perda de calibre, provocando obstrução segmentar no ramo póstero lateral da artéria circunflexa.', false),
(gen_random_uuid(), '0d201f5c-241a-46fa-aa1f-abb929e14340', 'c', 'Na imagem C, tomada em projeção oblíqua esquerda caudal (spider view), observamos uma anatomia com tronco trifurcado e lesão grave e longa na artéria descendente anterior.', false),
(gen_random_uuid(), '0d201f5c-241a-46fa-aa1f-abb929e14340', 'd', 'A imagem D, tomada em duas projeções, corresponde à imagem da artéria coronária direita sem lesões significantes.', false),
(gen_random_uuid(), '0d201f5c-241a-46fa-aa1f-abb929e14340', 'e', 'Na imagem E, a circulação coronária é definida como do tipo dominância esquerda com lesão isolada do ramo descendente posterior.', true),

(gen_random_uuid(), 'b6ba1547-65fa-41b8-a644-1c8e4081a636', 'a', 'Homem de 62 anos, diabético, com angina estável de grandes esforços, sem outros sintomas, e teste ergométrico interrompido por dor torácica sugestiva de angina ao atingir 9 MET.', false),
(gen_random_uuid(), 'b6ba1547-65fa-41b8-a644-1c8e4081a636', 'b', 'Mulher de 60 anos, tabagista e hipertensa, com angina estável de esforços habituais, evoluindo com dispneia paroxística noturna, ortopneia e dispneia e dor anginosa de grandes esforços, sem teste provocativo de isquemia ainda realizado.', true),
(gen_random_uuid(), 'b6ba1547-65fa-41b8-a644-1c8e4081a636', 'c', 'Mulher de 75 anos, portadora de diabetes e hipertensão, com quadro de angina estável de grandes esforços, com ecoestresse mostrando defeito de perfusão em parede lateral, com dose de dobutamina > 10mcg/kg/min.', false),
(gen_random_uuid(), 'b6ba1547-65fa-41b8-a644-1c8e4081a636', 'd', 'Homem de 70 anos, portador de dislipidemia, com angina estável de esforços habituais, com teste ergométrico interrompido por dor anginosa ao atingir 8 MET e cintilografia de perfusão miocárdica evidenciando hipoperfusão transitória de pequena extensão e gravidade em parede inferior.', false),
(gen_random_uuid(), 'b6ba1547-65fa-41b8-a644-1c8e4081a636', 'e', 'Homem de 52 anos, sem antecedentes pessoais dignos de nota, com quadro de dor torácica sugestiva de angina estável aos esforços habituais (CCS II), com cintilografia miocárdica mostrando hipoperfusão transitória de moderada intensidade e pequena extensão em parede lateral, sem disfunção do ventrículo esquerdo no estresse.', false),

(gen_random_uuid(), 'f8a4d091-01d1-4672-90df-6f48ad56d519', 'a', 'Stent coronariano e clipe de aneurisma cerebral.', false),
(gen_random_uuid(), 'f8a4d091-01d1-4672-90df-6f48ad56d519', 'b', 'Próteses valvares metálicas e stent coronariano.', true),
(gen_random_uuid(), 'f8a4d091-01d1-4672-90df-6f48ad56d519', 'c', 'Clipe de aneurisma cerebral e implantes cocleares.', false),
(gen_random_uuid(), 'f8a4d091-01d1-4672-90df-6f48ad56d519', 'd', 'Implantes cocleares e sutura metálica de esterno.', false),
(gen_random_uuid(), 'f8a4d091-01d1-4672-90df-6f48ad56d519', 'e', 'Sutura metálica de esterno e fragmentos metálicos oculares.', false),

(gen_random_uuid(), '00b11b0f-677e-402d-be2b-8edf054f94ed', 'a', 'Ponte miocárdica', true),
(gen_random_uuid(), '00b11b0f-677e-402d-be2b-8edf054f94ed', 'b', 'Vasoespasmo coronariano', false),
(gen_random_uuid(), '00b11b0f-677e-402d-be2b-8edf054f94ed', 'c', 'Doença ateromatosa coronária', false),
(gen_random_uuid(), '00b11b0f-677e-402d-be2b-8edf054f94ed', 'd', 'Embolização para artéria coronária', false),
(gen_random_uuid(), '00b11b0f-677e-402d-be2b-8edf054f94ed', 'e', 'Dissecção da artéria coronária', false),

(gen_random_uuid(), '0d151b1c-435f-42cb-a6c7-b7d428516a1a', 'a', 'Doença pulmonar obstrutiva crônica e hipertensão pulmonar.', false),
(gen_random_uuid(), '0d151b1c-435f-42cb-a6c7-b7d428516a1a', 'b', 'Fístula arteriovenosa e hiperviscosidade.', false),
(gen_random_uuid(), '0d151b1c-435f-42cb-a6c7-b7d428516a1a', 'c', 'Doença de microcirculação e alterações no tônus vascular.', true),
(gen_random_uuid(), '0d151b1c-435f-42cb-a6c7-b7d428516a1a', 'd', 'Hipertireoidismo e apneia do sono.', false),
(gen_random_uuid(), '0d151b1c-435f-42cb-a6c7-b7d428516a1a', 'e', 'Fibrilação atrial e distúrbios psiquiátricos.', false),

(gen_random_uuid(), '2f850e7e-259b-432d-ae14-486bc2183216', 'a', 'Manter tratamento clínico.', true),
(gen_random_uuid(), '2f850e7e-259b-432d-ae14-486bc2183216', 'b', 'Manter tratamento clínico e solicitar cintilografia miocárdica.', false),
(gen_random_uuid(), '2f850e7e-259b-432d-ae14-486bc2183216', 'c', 'Manter tratamento clínico e solicitar dosagem sérica da proteína C reativa ultrassensível para adequar dosagem de estatina.', false),
(gen_random_uuid(), '2f850e7e-259b-432d-ae14-486bc2183216', 'd', 'Manter tratamento clínico e solicitar angiotomocoronariografia.', false),
(gen_random_uuid(), '2f850e7e-259b-432d-ae14-486bc2183216', 'e', 'Manter tratamento clínico e solicitar teste de esforço a cada 6 meses.', false),

(gen_random_uuid(), 'ea746dff-ddcb-4b71-a5f1-47a1d88aaf9e', 'a', 'O cateterismo normal descarta a possibilidade de isquemia miocárdica, devendo-se procurar diagnósticos alternativos para o caso em questão.', false),
(gen_random_uuid(), 'ea746dff-ddcb-4b71-a5f1-47a1d88aaf9e', 'b', 'O diagnóstico mais provável é de angina variante de Prinzmetal, e a paciente deve ser tratada preferencialmente com bloqueadores dos canais de cálcio isolados ou em associação com nitratos de longa duração.', false),
(gen_random_uuid(), 'ea746dff-ddcb-4b71-a5f1-47a1d88aaf9e', 'c', 'O diagnóstico mais provável é o de angina microvascular e não existe terapia recomendada por diretrizes para o tratamento dessa condição, podendo-se tentar qualquer combinação de antianginosos.', true),
(gen_random_uuid(), 'ea746dff-ddcb-4b71-a5f1-47a1d88aaf9e', 'd', 'A paciente apresenta quadro de angina secundária à ponte miocárdica em terço médio da artéria descendente anterior, e o tratamento deve ser com betabloqueadores ou nitratos de longa duração.', false),
(gen_random_uuid(), 'ea746dff-ddcb-4b71-a5f1-47a1d88aaf9e', 'e', 'A paciente apresenta quadro de angina microvascular, sendo necessário o uso de métodos de imagem endovascular como iFR (isant wave-free ratio) ou IVUS (ultrassom intravascular) para descartar doença coronariana epicárdica obstrutiva.', false),

(gen_random_uuid(), '8218d48a-9740-40c6-bca0-28fadacfc87a', 'a', 'Dentre as variáveis da imagem cintilográfica, alterações de perfusão em múltiplas áreas e aumento transitório do ventrículo esquerdo não identificam os pacientes de maior risco.', false),
(gen_random_uuid(), '8218d48a-9740-40c6-bca0-28fadacfc87a', 'b', 'Das variáveis eletrocardiográficas, o infradesnivelamento do segmento ST, independentemente do tempo de aparecimento e de sua magnitude, não discrimina os pacientes em categorias de risco.', false),
(gen_random_uuid(), '8218d48a-9740-40c6-bca0-28fadacfc87a', 'c', 'A captação pulmonar aumentada do radiofármaco reflete invariavelmente a disfunção ventricular direita após o estresse.', false),
(gen_random_uuid(), '8218d48a-9740-40c6-bca0-28fadacfc87a', 'd', 'A cintilografia com estresse farmacológico não deve ser indicada na avaliação pré-operatória de cirurgia não cardíaca de pacientes com três ou mais fatores de risco para DAC, pois apresenta baixa sensibilidade, sobretudo em pacientes que podem se exercitar.', false),
(gen_random_uuid(), '8218d48a-9740-40c6-bca0-28fadacfc87a', 'e', 'A cintilografia de perfusão miocárdica está indicada, com fins diagnósticos, para pacientes com eletrocardiograma (ECG) de repouso anormal e na dificuldade de interpretação do segmento ST, como na presença de hipertrofia ventricular esquerda (HVE) e bloqueio de ramo esquerdo (BRE), sobretudo nos pacientes de maior probabilidade de doença.', true),

(gen_random_uuid(), '3342e291-fccb-4555-9d69-5b4e766d88b9', 'a', 'Defeitos isolados de perfusão de tamanho moderado durante teste de imagem com estresse.', true),
(gen_random_uuid(), '3342e291-fccb-4555-9d69-5b4e766d88b9', 'b', 'Disfunção do ventrículo esquerdo em repouso grave (FE < 0,35).', false),
(gen_random_uuid(), '3342e291-fccb-4555-9d69-5b4e766d88b9', 'c', 'Moderados defeitos de perfusão sem dilatação ventricular esquerda ou captação pulmonar durante teste de imagem com estresse.', false),
(gen_random_uuid(), '3342e291-fccb-4555-9d69-5b4e766d88b9', 'd', 'Disfunção ventricular esquerda ao teste de imagem com estresse (FE entre 0,35 e 0,45).', false),
(gen_random_uuid(), '3342e291-fccb-4555-9d69-5b4e766d88b9', 'e', 'Nenhuma das anteriores.', false),

(gen_random_uuid(), '50041041-a756-4726-969a-ecb03af6f79b', 'a', 'Está indicada na avaliação de pacientes assintomáticos para estratificar o risco cardiovascular global.', false),
(gen_random_uuid(), '50041041-a756-4726-969a-ecb03af6f79b', 'b', 'Não apresenta boa acurácia na avaliação da patência dos enxertos coronarianos em pacientes já revascularizados.', false),
(gen_random_uuid(), '50041041-a756-4726-969a-ecb03af6f79b', 'c', 'A presença de calcificação coronariana acentuada não representa uma limitação ao exame, pois facilita a identificação das placas ateroscleróticas.', false),
(gen_random_uuid(), '50041041-a756-4726-969a-ecb03af6f79b', 'd', 'Os pacientes com maior potencial de se beneficiar do exame são aqueles com probabilidade alta de lesões coronarianas obstrutivas significativas pelos critérios de Diamond/Forrester.', false),
(gen_random_uuid(), '50041041-a756-4726-969a-ecb03af6f79b', 'e', 'Apresenta excelente acurácia para detectar e, principalmente, para excluir a presença de lesões obstrutivas significativas em pacientes sintomáticos com suspeita de doença aterosclerótica coronariana.', true),

(gen_random_uuid(), '75c55ec2-85f4-417a-a460-06c57aca141c', 'a', 'Solicitar angiotomografia coronária, iniciar clopidogrel e associar trimetazidina', false),
(gen_random_uuid(), '75c55ec2-85f4-417a-a460-06c57aca141c', 'b', 'Solicitar ecocardiograma de estresse farmacológico e aumentar dose de AAS.', false),
(gen_random_uuid(), '75c55ec2-85f4-417a-a460-06c57aca141c', 'c', 'Solicitar coronariografia e avaliar teste provocativo de espasmo coronariano.', false),
(gen_random_uuid(), '75c55ec2-85f4-417a-a460-06c57aca141c', 'd', 'Otimizar tratamento clínico e realizar nova cintilografia após 6 meses.', false),
(gen_random_uuid(), '75c55ec2-85f4-417a-a460-06c57aca141c', 'e', 'Solicitar coronariografia e avaliar revascularização miocárdica.', true),

(gen_random_uuid(), '8f893b6c-367d-42a8-8dc8-f5e8e724d09b', 'a', 'Alteração da contratilidade regional em 1 ou 2 segmentos no território da artéria descendente anterior; defeitos de perfusão estresse-induzidos envolvendo ≥ 5% do miocárdio; escore de cálcio > 100 unidades Agatston.', false),
(gen_random_uuid(), '8f893b6c-367d-42a8-8dc8-f5e8e724d09b', 'b', 'Aparecimento de bloqueio de ramo esquerdo durante o teste ergométrico; lesão de tronco da artéria coronária esquerda > 50% pela angiotomografia; queda da fração de ejeção do ventrículo esquerdo ≥ 5% estresse-induzida.', false),
(gen_random_uuid(), '8f893b6c-367d-42a8-8dc8-f5e8e724d09b', 'c', 'Taquicardia ventricular esforço-induzida; ≥ 1 mm de depressão do segmento ST acompanhado de angina; fração de ejeção do ventrículo esquerdo em repouso < 50%.', false),
(gen_random_uuid(), '8f893b6c-367d-42a8-8dc8-f5e8e724d09b', 'd', 'Defeitos de perfusão em repouso envolvendo ≥ 10% do miocárdio; lesão ≥ 70% do segmento proximal da artéria descendente anterior pela angiotomografia; aparecimento de bloqueio de ramo direito durante o teste ergométrico.', false),
(gen_random_uuid(), '8f893b6c-367d-42a8-8dc8-f5e8e724d09b', 'e', 'Dilatação do ventrículo esquerdo estresse-induzida; escore de cálcio > 400 unidades Agatston; ≥ 2 mm de depressão do segmento ST em baixa carga ou persistente durante a recuperação no teste ergométrico.', true),

(gen_random_uuid(), '6d0a49ad-d8f6-447c-a4c3-323d8b634886', 'a', 'O desenvolvimento de infradesnivelamento do segmento ST está frequentemente relacionado à doença multiarterial.', false),
(gen_random_uuid(), '6d0a49ad-d8f6-447c-a4c3-323d8b634886', 'b', 'Aminofilina é o fármaco de escolha para antagonizar os efeitos colaterais.', false),
(gen_random_uuid(), '6d0a49ad-d8f6-447c-a4c3-323d8b634886', 'c', 'Dor precordial é frequente e com baixa especificidade diagnóstica.', false),
(gen_random_uuid(), '6d0a49ad-d8f6-447c-a4c3-323d8b634886', 'd', 'É contraindicado em portadores de asma brônquica com prova funcional respiratória com padrão obstrutivo moderado ou grave.', false),
(gen_random_uuid(), '6d0a49ad-d8f6-447c-a4c3-323d8b634886', 'e', 'Associação com caminhada na esteira em baixa carga diminui os efeitos colaterais, mas piora a qualidade das imagens cintilográficas.', true),

(gen_random_uuid(), '92631e83-004f-4d82-bcc5-4d6210d97e17', 'a', 'Aquele com a angina de peito desencadeada pela atividade física', false),
(gen_random_uuid(), '92631e83-004f-4d82-bcc5-4d6210d97e17', 'b', 'Aquele com antecedentes de arritmias supraventricular e ventricular.', false),
(gen_random_uuid(), '92631e83-004f-4d82-bcc5-4d6210d97e17', 'c', 'Aquele com infarto do miocárdio prévio.', false),
(gen_random_uuid(), '92631e83-004f-4d82-bcc5-4d6210d97e17', 'd', 'Aquele com disfunção sistólica isolada do ventrículo direito.', true),
(gen_random_uuid(), '92631e83-004f-4d82-bcc5-4d6210d97e17', 'e', 'Aquele com insuficiência cardíaca congestiva, classes funcionais II e III da New York Heart Association.', false),

(gen_random_uuid(), '17d10f36-4ab0-4b82-a62f-de38592655de', 'a', 'É especialmente útil na investigação diagnóstica de pacientes com dor no peito na sala de emergência', false),
(gen_random_uuid(), '17d10f36-4ab0-4b82-a62f-de38592655de', 'b', 'A necessidade do uso do contraste iodado representa uma limitação em pacientes com função renal comprometida', false),
(gen_random_uuid(), '17d10f36-4ab0-4b82-a62f-de38592655de', 'c', 'Quanto maior for o escore de cálcio do paciente, melhor será o seu prognóstico cardiovascular nos próximos 2 a 5 anos.', false),
(gen_random_uuid(), '17d10f36-4ab0-4b82-a62f-de38592655de', 'd', 'Está indicado na avaliação de pacientes assintomáticos com risco cardiovascular intermediário pelo escore de Framingham.', true),
(gen_random_uuid(), '17d10f36-4ab0-4b82-a62f-de38592655de', 'e', 'Com o objetivo de determinar a necessidade de suplementação nutricional de cálcio oral, está indicado na avaliação de pacientes coronariopatas idosos (> 65 anos) com diagnóstico de osteoporose estabelecido na densitometria óssea.', false),

(gen_random_uuid(), 'e9ad8faf-b9f9-4be6-b83f-989da8121ea8', 'a', 'Suspeita de anomalias das artérias coronárias.', false),
(gen_random_uuid(), 'e9ad8faf-b9f9-4be6-b83f-989da8121ea8', 'b', 'Avaliação de pacientes com baixa probabilidade de doença arterial coronariana e com testes de isquemia positivos.', false),
(gen_random_uuid(), 'e9ad8faf-b9f9-4be6-b83f-989da8121ea8', 'c', 'Avaliação de pacientes com dor torácica aguda com alta probabilidade de doença arterial coronariana e com marcadores de necrose miocárdica positivos.', true),
(gen_random_uuid(), 'e9ad8faf-b9f9-4be6-b83f-989da8121ea8', 'd', 'Avaliação de pacientes com dor torácica aguda com probabilidade baixa ou intermediária de doença arterial coronariana com eletrocardiograma e marcadores de necrose miocárdica normais ou duvidosos.', false),
(gen_random_uuid(), 'e9ad8faf-b9f9-4be6-b83f-989da8121ea8', 'e', 'Avaliação de pacientes com probabilidade intermediária de doença arterial coronariana com teste ergométrico negativo e cintilografia de perfusão miocárdica apresentando isquemia discreta.', false),

(gen_random_uuid(), 'd6375732-abf5-4c03-a366-8dd32c0a7f8a', 'a', 'Insuficiência renal aguda ou disfunção renal crônica não dependente de diálise', false),
(gen_random_uuid(), 'd6375732-abf5-4c03-a366-8dd32c0a7f8a', 'b', 'Infarto agudo do miocárdio no paciente em programa de hemodiálise', true),
(gen_random_uuid(), 'd6375732-abf5-4c03-a366-8dd32c0a7f8a', 'c', 'Febre inexplicável ou presença de infecção ativa não tratada', false),
(gen_random_uuid(), 'd6375732-abf5-4c03-a366-8dd32c0a7f8a', 'd', 'Desequilíbrio hidroeletrolítico, sobretudo hipocalemia', false),
(gen_random_uuid(), 'd6375732-abf5-4c03-a366-8dd32c0a7f8a', 'e', 'Acidente vascular encefálico agudo.', false),

(gen_random_uuid(), '2dcf045c-3d12-4645-b3da-b3319a75f60e', 'a', 'O escore de cálcio coronariano por tomografia computadorizada está recomendado para pacientes sintomáticos de risco intermediário.', false),
(gen_random_uuid(), '2dcf045c-3d12-4645-b3da-b3319a75f60e', 'b', 'As lesões coronarianas são significativas quando há obstrução de uma ou mais artérias epicárdicas com, no mínimo, 70% de estenose e/ou tronco coronariano esquerdo com, no mínimo, 80%, sendo tais obstruções avaliadas e mensuradas pela angiografia coronariana.', false),
(gen_random_uuid(), '2dcf045c-3d12-4645-b3da-b3319a75f60e', 'c', 'A cintilografia de perfusão miocárdica com estresse farmacológico está recomendada para paciente com probabilidade pré-teste baixa e que tenha eletrocardiograma interpretável ou incapacidade de exercício físico.', false),
(gen_random_uuid(), '2dcf045c-3d12-4645-b3da-b3319a75f60e', 'd', 'A angiografia coronariana é recomendada para pacientes de baixo risco em testes não invasivos, independentemente da presença de angina.', false),
(gen_random_uuid(), '2dcf045c-3d12-4645-b3da-b3319a75f60e', 'e', 'A cintilografia de perfusão miocárdica está recomendada para paciente com probabilidade pré-teste intermediária ou alta e que tenha eletrocardiograma não interpretável.', true),

(gen_random_uuid(), 'f2472c62-eeaa-4a39-827e-1808b8a53e96', 'a', 'Não há superioridade inequívoca entre a abordagem da doença arterial coronariana e carotídea sequencial ou combinada no mesmo procedimento.', true),
(gen_random_uuid(), 'f2472c62-eeaa-4a39-827e-1808b8a53e96', 'b', 'A abordagem por stent ou endarterectomia da doença carotídea não deve ser considerada no pré-operatório da revascularização coronariana cirúrgica.', false),
(gen_random_uuid(), 'f2472c62-eeaa-4a39-827e-1808b8a53e96', 'c', 'A doença carotídea desse paciente deve ser abordada pelo risco significativamente aumentado de acidente vascular encefálico durante a cirurgia de revascularização miocárdica, mesmo em pacientes assintomáticos do ponto de vista cerebrovascular.', false),
(gen_random_uuid(), 'f2472c62-eeaa-4a39-827e-1808b8a53e96', 'd', 'Caso se opte por tratamento cirúrgico tanto da doença arterial coronariana quanto da doença arterial carotídea, a melhor opção é a abordagem inicial da doença carotídea, seguida pela intervenção da doença arterial coronariana.', false),
(gen_random_uuid(), 'f2472c62-eeaa-4a39-827e-1808b8a53e96', 'e', 'Caso o paciente apresentasse episódios de ataques isquêmicos transitórios de repetição, a abordagem da doença carotídea deveria ser realizada em primeiro lugar, deixando a abordagem cirúrgica da doença coronariana em segundo lugar.', false),

(gen_random_uuid(), 'd9a50b9d-0ca7-4b14-bd62-b6d6e13572c7', 'a', 'A angioplastia de uma oclusão coronária crônica, definida como fluxo TIMI 0 no segmento arterial ocluído por período maior que três meses, é indicada para todos os pacientes, independentemente de sintomas limitantes, evidências de disfunção ventricular ou viabilidade regional.', false),
(gen_random_uuid(), 'd9a50b9d-0ca7-4b14-bd62-b6d6e13572c7', 'b', 'A intervenção coronária percutânea (ICP) deve ser sistematicamente realizada com a intenção de melhorar a sobrevida de paciente com doença arterial coronariana (DAC) estável e estenose coronariana que não seja anatômica ou funcionalmente significativa (por exemplo: lesão < 70% em artéria coronária principal; reserva de fluxo fracionado [RFF > 0,80]; e isquemia ausente ou leve em teste não invasivo).', false),
(gen_random_uuid(), 'd9a50b9d-0ca7-4b14-bd62-b6d6e13572c7', 'c', 'Quando a avaliação não invasiva de isquemia por imagem for contraindicada, inconclusiva ou não disponível, a avaliação da reserva de fluxo fracionado (RFF) durante infusão de adenosina não auxilia na identificação de estenoses hemodinâmica ou funcionalmente significativas e, portanto, indutoras de isquemia.', false),
(gen_random_uuid(), 'd9a50b9d-0ca7-4b14-bd62-b6d6e13572c7', 'd', 'Pacientes com lesões triarteriais complexas, revascularização incompleta com intervenção coronária percutânea (ICP) e Syntax escore > 33 são favoráveis à revascularização miocárdica cirúrgica.', true),
(gen_random_uuid(), 'd9a50b9d-0ca7-4b14-bd62-b6d6e13572c7', 'e', 'Estudos com "stent convencional" demonstraram que o tratamento clínico otimizado proporciona melhores resultados em comparação à revascularização imediata de pacientes com reserva de fluxo fracionado (RFF) < 0,80. A utilização desta pontuação é particularmente útil em lesões angiograficamente maiores que 90%.', false),

(gen_random_uuid(), 'f42b3754-b5d8-43bf-84b4-3acc668aac7b', 'a', 'Tronco da coronária esquerda com escore Syntax de 20.', false),
(gen_random_uuid(), 'f42b3754-b5d8-43bf-84b4-3acc668aac7b', 'b', 'Doença triarterial com escore Syntax de 33.', true),
(gen_random_uuid(), 'f42b3754-b5d8-43bf-84b4-3acc668aac7b', 'c', 'Tronco da coronária esquerda com escore Syntax de 30.', false),
(gen_random_uuid(), 'f42b3754-b5d8-43bf-84b4-3acc668aac7b', 'd', 'Paciente uniarterial com obstrução proximal de artéria descendente anterior.', false),
(gen_random_uuid(), 'f42b3754-b5d8-43bf-84b4-3acc668aac7b', 'e', 'Doença triarterial com escore Syntax de 20.', false),

(gen_random_uuid(), 'ff2f590e-4dfd-43ce-85f5-89effec3f1ed', 'a', 'O clopidogrel apresenta metabolismo hepático via citocromo P450 a fim de ser transformado em seu metabólito ativo, enquanto o prasugrel já é um fármaco ativo que não necessita de ativação hepática para atingir o efeito terapêutico.', false),
(gen_random_uuid(), 'ff2f590e-4dfd-43ce-85f5-89effec3f1ed', 'b', 'O ticagrelor bloqueia de maneira irreversível o receptor P2Y12 plaquetário, enquanto o prasugrel o faz de maneira reversível.', false),
(gen_random_uuid(), 'ff2f590e-4dfd-43ce-85f5-89effec3f1ed', 'c', 'O clopidogrel e o ticagrelor devem ser suspensos idealmente pelo menos cinco dias antes de procedimentos cirúrgicos eletivos, enquanto o prasugrel deve ser suspenso no mínimo sete dias antes.', true),
(gen_random_uuid(), 'ff2f590e-4dfd-43ce-85f5-89effec3f1ed', 'd', 'Os inibidores de bomba de prótons não apresentam nenhuma interação com esses medicamentos.', false),
(gen_random_uuid(), 'ff2f590e-4dfd-43ce-85f5-89effec3f1ed', 'e', 'Variabilidades na resposta ao clopidogrel podem ser explicadas por interações medicamentosas, porém fatores genéticos não foram implicados até o momento.', false),

(gen_random_uuid(), '5c677c4d-c162-4e00-9844-56eb61bf4f6c', 'a', 'nessa população, quando necessário, é preferencialmente indicado o uso hipoglicemiantes orais como a DPP-4 e/ou análogos da GLP-1 sendo a metformina considerada uma droga de segunda escolha.', false),
(gen_random_uuid(), '5c677c4d-c162-4e00-9844-56eb61bf4f6c', 'b', 'dentre os fármacos utilizados no tratamento da DACC com função ventricular preservada, apenas o ácido acetilsalicílico e os inibidores da enzima HMG-CoA redutase demonstraram redução convincente de mortalidade e morbidade.', true),
(gen_random_uuid(), '5c677c4d-c162-4e00-9844-56eb61bf4f6c', 'c', 'a ivabradina é um inibidor específico da corrente If no nó sinusal, atua reduzindo a frequência cardíaca, a contratilidade cardíaca e a condução intracardíaca e apenas casos selecionados são candidatos ao seu uso pelos seus efeitos adversos.', false),
(gen_random_uuid(), '5c677c4d-c162-4e00-9844-56eb61bf4f6c', 'd', 'os inibidores da enzima conversora de angiotensina são fármacos antianginosos de primeira linha, estão indicados em todos os pacientes para todos os pacientes portadores de doença arterial coronariana independente da presença ou não de disfunção sistólica ventricular preservada.', false),
(gen_random_uuid(), '5c677c4d-c162-4e00-9844-56eb61bf4f6c', 'e', 'a trimetazidina é um fármaco de ação metabólica, que exerce um efeito independente da frequência cardíaca, contratilidade e pressão arterial. Atua por meio da inibição da enzima–cetoacil coenzima A tiolase. Sua eficácia clínica é equivalente aos nitratos, antagonistas de canal de cálcio e betabloqueadores, porém confere baixa tolerância ao exercício em comparação a terapia padrão.', false),

(gen_random_uuid(), '69554ea7-6e3c-40d9-af71-ac74d9973a05', 'a', 'A ivabradina é um inibidor seletivo da corrente das células marca-passo cardíacas dos nós sinusal e atrioventricular.', false),
(gen_random_uuid(), '69554ea7-6e3c-40d9-af71-ac74d9973a05', 'b', 'Não atua na redução da frequência cardíaca durante o esforço físico.', false),
(gen_random_uuid(), '69554ea7-6e3c-40d9-af71-ac74d9973a05', 'c', 'Favorece o controle da condução atrioventricular na fibrilação atrial.', false),
(gen_random_uuid(), '69554ea7-6e3c-40d9-af71-ac74d9973a05', 'd', 'A posologia usual é de 7,5 mg de oito em oito horas.', false),
(gen_random_uuid(), '69554ea7-6e3c-40d9-af71-ac74d9973a05', 'e', 'A melhora do fluxo sanguíneo coronário é decorrente do prolongamento da diástole.', true),

(gen_random_uuid(), '3a6aafa0-0460-4fb5-8fb0-d9963ad250cb', 'a', 'inibidores do cotransportador sódio-glicose 2 (SGLT2) inibem a reabsorção urinária de glicose e promovem diurese osmótica. Apesar da redução do risco de morte cardiovascular pela empagliflozina, outros fármacos dessa classe podem estar associados a maior risco de amputações em membros inferiores', false),
(gen_random_uuid(), '3a6aafa0-0460-4fb5-8fb0-d9963ad250cb', 'b', 'as sulfonilureias estão associadas a maior risco de hipoglicemia, ao subsequente estímulo do sistema adrenérgico com potenciais efeitos adversos cardiovasculares e consideradas um fármaco de segunda linha', false),
(gen_random_uuid(), '3a6aafa0-0460-4fb5-8fb0-d9963ad250cb', 'c', 'as biguanidas (metformina) reduzem a glicose sanguínea por diminuírem a produção hepática de glicose e melhorarem a sensibilidade à insulina; além disso, estão associadas à redução ponderal e à melhora do perfil lipídico com baixo risco de hipoglicemia', false),
(gen_random_uuid(), '3a6aafa0-0460-4fb5-8fb0-d9963ad250cb', 'd', 'as tiazolidinedionas aumentam a sensibilidade à insulina nos tecidos-alvo e estão associadas a ganho de peso, edema periférico e aumento do risco de desenvolvimento e agravamento da insuficiência cardíaca, estando contraindicadas para pacientes com classes funcionais III e IV da New York Heart Association', false),
(gen_random_uuid(), '3a6aafa0-0460-4fb5-8fb0-d9963ad250cb', 'e', 'os inibidores da dipeptidil peptidase 4 (DPP-4) reduzem o risco de eventos cardiovasculares maiores e o risco de hospitalização por insuficiência cardíaca, sendo fármaco de primeira escolha para esta população', true),

(gen_random_uuid(), '233e4621-ed84-42f7-b27d-e1c36f4515b5', 'a', 'Uma característica que define o miocárdio atordoado isolado é que a função ventricular permanece deprimida, enquanto a perfusão miocárdica está normal.', true),
(gen_random_uuid(), '233e4621-ed84-42f7-b27d-e1c36f4515b5', 'b', 'As isquemias produzidas por aumento de demanda miocárdica por oxigênio são incapazes de levar a um miocárdio atordoado.', false),
(gen_random_uuid(), '233e4621-ed84-42f7-b27d-e1c36f4515b5', 'c', 'A disfunção segmentar crônica causada por isquemia de repetição é rara em pacientes com cardiomiopatia isquêmica.', false),
(gen_random_uuid(), '233e4621-ed84-42f7-b27d-e1c36f4515b5', 'd', 'No miocárdio agudamente atordoado, a função ventricular esquerda não responde ao estímulo com inotrópicos.', false),
(gen_random_uuid(), '233e4621-ed84-42f7-b27d-e1c36f4515b5', 'e', 'O miocárdio hibernante é o principal responsável pela disfunção ventricular pós-operatória após uma cirurgia com circulação extracorpórea.', false);


